async def act(page):
    """
    From the current Manage Products page state: close the visible popup if present,
    fill the Search filter with 'Desiree black xs', click the Search button (using an
    unambiguous get_by_role path), then scan the product rows for those containing
    'desiree', 'black', and 'xs'. For each matching product, navigate to its Edit
    page (page.goto), locate the Price input, increase it by 37% (rounded to 2
    decimals), fill the new value, click Save, and return to the Manage Products
    grid to continue.

    This act() continues from the current UI state and performs only the NEW
    actions needed now.
    """
    import re
    import asyncio
    from decimal import Decimal, ROUND_HALF_UP

    async def safe_count(loc):
        if loc is None:
            return 0
        if not hasattr(loc, 'count'):
            return 0
        try:
            return await loc.count()
        except Exception:
            return 0

    async def safe_nth(loc, idx):
        if loc is None:
            return None
        if not hasattr(loc, 'nth') or not hasattr(loc, 'count'):
            return None
        try:
            c = await loc.count()
        except Exception:
            return None
        if idx < 0 or idx >= c:
            return None
        try:
            return loc.nth(idx)
        except Exception:
            return None

    def parse_price(text: str) -> Decimal:
        if not text:
            return Decimal('0.00')
        s = str(text)
        cleaned = re.sub(r"[^0-9.\-]", "", s)
        if cleaned == "":
            return Decimal('0.00')
        if cleaned.count('.') > 1:
            parts = cleaned.split('.')
            cleaned = ''.join(parts[:-1]) + '.' + parts[-1]
        try:
            return Decimal(cleaned)
        except Exception:
            return Decimal('0.00')

    def format_price(d: Decimal) -> str:
        return str(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

    # Ensure page is relatively settled
    try:
        await page.wait_for_load_state('networkidle')
    except Exception:
        await asyncio.sleep(1)

    # 1) Close obvious popup if present by clicking any button that looks like a close control
    try:
        all_buttons = page.get_by_role('button')
        total = await safe_count(all_buttons)
        for i in range(total):
            btn = await safe_nth(all_buttons, i)
            if btn is None:
                continue
            name = ''
            try:
                name = (await btn.get_attribute('aria-label')) or ''
            except Exception:
                name = ''
            if not name:
                try:
                    name = (await btn.get_attribute('title')) or ''
                except Exception:
                    name = ''
            if not name:
                try:
                    name = (await btn.inner_text()) or ''
                except Exception:
                    name = ''
            ln = name.strip().lower()
            if 'close' in ln or ln in ('×', 'x', '✕'):
                try:
                    await btn.click()
                    await asyncio.sleep(0.35)
                except Exception:
                    pass
    except Exception:
        pass

    # 2) Fill the Search group textbox with the filter 'Desiree black xs'
    try:
        search_group = page.get_by_role('group', name='Search')
    except Exception:
        search_group = None

    if search_group is not None and await safe_count(search_group.get_by_role('textbox')) > 0:
        try:
            await search_group.get_by_role('textbox').nth(0).fill('Desiree black xs')
        except Exception:
            try:
                any_tb = page.get_by_role('textbox')
                if await safe_count(any_tb) > 0:
                    await any_tb.nth(0).fill('Desiree black xs')
            except Exception:
                pass

    # 3) Click the Search button using a full get_by_role path (row that contains the Search button)
    try:
        rows_with_search = page.get_by_role('row').filter(has=page.get_by_role('button', name='Search'))
        if await safe_count(rows_with_search) > 0:
            search_row = await safe_nth(rows_with_search, 0)
            if search_row is not None:
                search_btn = search_row.get_by_role('button', name='Search')
                if await safe_count(search_btn) > 0:
                    await search_btn.nth(0).click()
                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await asyncio.sleep(1)
    except Exception:
        pass

    # 4) Scan visible product rows and collect Edit hrefs for rows that contain desiree, black, xs
    candidate_hrefs = []
    try:
        rows = page.get_by_role('row')
        rc = await safe_count(rows)
        for ri in range(rc):
            row = await safe_nth(rows, ri)
            if row is None:
                continue
            try:
                text = (await row.inner_text() or '').lower()
            except Exception:
                text = ''
            if 'desiree' in text and 'black' in text and 'xs' in text:
                # prefer explicit Edit link
                try:
                    edit_links = row.get_by_role('link', name='Edit')
                except Exception:
                    edit_links = None
                el = await safe_nth(edit_links, 0)
                if el is not None:
                    try:
                        href = await el.get_attribute('href')
                    except Exception:
                        href = None
                    if href:
                        candidate_hrefs.append(href)
                        continue
                # fallback: any link in the row
                try:
                    links = row.get_by_role('link')
                except Exception:
                    links = None
                lc = await safe_count(links)
                for j in range(lc):
                    l = await safe_nth(links, j)
                    if l is None:
                        continue
                    try:
                        h = await l.get_attribute('href')
                    except Exception:
                        h = None
                    if h:
                        candidate_hrefs.append(h)
                        break
    except Exception:
        pass

    # If no candidates found, stop (pagination or different filters would be required)
    if not candidate_hrefs:
        return

    # 5) For each candidate edit page: navigate, change price by +37%, save, return to grid
    for href in candidate_hrefs:
        try:
            # Use page.goto to navigate to the edit page
            await page.goto(href)
            try:
                await page.wait_for_load_state('networkidle')
            except Exception:
                await asyncio.sleep(0.5)

            # Locate the price input with prioritized strategies
            price_field = None
            current_price_text = None
            strategies = [
                lambda: page.get_by_role('spinbutton', name='Price'),
                lambda: page.get_by_role('textbox', name='Price'),
                lambda: page.get_by_label('Price'),
                lambda: page.get_by_role('spinbutton'),
                lambda: page.get_by_role('textbox')
            ]
            for f in strategies:
                try:
                    loc = f()
                except Exception:
                    loc = None
                if loc is None:
                    continue
                if not hasattr(loc, 'count') or not hasattr(loc, 'nth'):
                    continue
                if await safe_count(loc) == 0:
                    continue
                fld = await safe_nth(loc, 0)
                if fld is None:
                    continue
                val = None
                try:
                    val = await fld.input_value()
                except Exception:
                    try:
                        val = await fld.get_attribute('value')
                    except Exception:
                        val = None
                price_field = fld
                current_price_text = val
                if current_price_text:
                    break

            # Fallback: scrape document text for currency-like value
            if not current_price_text:
                page_text = ''
                try:
                    doc = page.get_by_role('document')
                except Exception:
                    doc = None
                if doc is not None and await safe_count(doc) > 0:
                    try:
                        page_text = await doc.nth(0).inner_text()
                    except Exception:
                        page_text = ''
                if not page_text:
                    try:
                        page_text = await page.inner_text()
                    except Exception:
                        page_text = ''
                m = re.search(r"\$?\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?)", page_text)
                if m:
                    current_price_text = m.group(0)

            if not current_price_text:
                # Can't find a price; return to grid and continue
                try:
                    await page.goto('/index.php/admin/catalog_product/')
                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await asyncio.sleep(0.5)
                except Exception:
                    pass
                continue

            cur = parse_price(current_price_text)
            new_price = (cur * Decimal('1.37')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            new_price_str = format_price(new_price)

            filled = False
            if price_field is not None:
                try:
                    await price_field.fill(new_price_str)
                    filled = True
                except Exception:
                    try:
                        await price_field.evaluate('(el, v) => el.value = v', new_price_str)
                        filled = True
                    except Exception:
                        filled = False

            if not filled:
                try:
                    tboxes = page.get_by_role('textbox')
                except Exception:
                    tboxes = None
                tc = await safe_count(tboxes)
                for k in range(tc):
                    tb = await safe_nth(tboxes, k)
                    if tb is None:
                        continue
                    try:
                        await tb.fill(new_price_str)
                        filled = True
                        break
                    except Exception:
                        try:
                            await tb.evaluate('(el, v) => el.value = v', new_price_str)
                            filled = True
                            break
                        except Exception:
                            continue

            # Click Save (try accessible Save button first)
