                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await asyncio.sleep(1)
                except Exception:
                    pass
            else:
                try:
                    all_btns = page.get_by_role('button')
                except Exception:
                    all_btns = None
                bc = await safe_count(all_btns)
                for bi in range(bc):
                    b = await safe_nth(all_btns, bi)
                    if b is None:
                        continue
                    name = ''
                    try:
                        name = (await b.get_attribute('aria-label')) or ''
                    except Exception:
                        name = ''
                    if not name:
                        try:
                            name = (await b.inner_text()) or ''
                        except Exception:
                            name = ''
                    if 'save' in name.lower():
                        try:
                            await b.click()
                            try:
                                await page.wait_for_load_state('networkidle')
                            except Exception:
                                await asyncio.sleep(1)
                        except Exception:
                            pass
                        break

            # Small pause and return to grid to continue
            await asyncio.sleep(0.6)
            try:
                await page.goto('/index.php/admin/catalog_product/')
                try:
                    await page.wait_for_load_state('networkidle')
